// Photo asset "logo-cropped" — added by the builder (their own real, local image).
// Use it in any page with:
//   <script src="./assets/logo-cropped.js"></script>
//   <img data-asset="logo-cropped" alt="describe the photo">
window.ASSETS = Object.assign(window.ASSETS || {}, { "logo-cropped": "data:image/png;base64," });
(function () {
  function apply() { document.querySelectorAll('img[data-asset="logo-cropped"]').forEach(function (img) { img.src = window.ASSETS["logo-cropped"]; }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();
